<?php
declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comisiones PROA — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{max-width:940px;margin:auto;padding:82px 14px 32px}h1{margin:0 0 5px}.sub{color:#64748b;margin-bottom:16px}.toolbar,.panel,.status{background:#fff;border-radius:15px;padding:14px;box-shadow:0 3px 12px #0f172a0d}.toolbar{display:grid;grid-template-columns:180px 1fr;gap:10px;margin-bottom:12px}.toolbar input,.form input,.form textarea,.form button{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:9px;font:inherit}.status{margin-bottom:12px}.status.ok{border-left:5px solid #16a34a}.status.no{border-left:5px solid #f59e0b}.big{font-size:24px;font-weight:900}.muted{font-size:12px;color:#64748b}.form{display:grid;grid-template-columns:1.4fr .6fr 1.5fr auto;gap:8px;align-items:end}.form button{background:#123b5d;color:#fff;font-weight:800;border:0;cursor:pointer}.form button:disabled{opacity:.45;cursor:not-allowed}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;padding:9px;border-bottom:1px solid #eef2f7;font-size:13px}.danger{border:0;background:#fee2e2;color:#991b1b;border-radius:8px;padding:7px 9px;font-weight:800;cursor:pointer}.total{margin-top:12px;text-align:right;font-size:20px;font-weight:900}.msg{margin-top:8px;font-size:12px;font-weight:700}@media(max-width:700px){.toolbar{grid-template-columns:1fr}.form{grid-template-columns:1fr}.wrap{padding-left:12px;padding-right:12px}}</style></head><body><main class="wrap"><h1>Comisiones PROA</h1><div class="sub">Registro privado de comisiones nominales reconocidas a Hache Natación</div><div class="toolbar"><input id="periodo" type="month"><div class="muted">Las comisiones de un mes solo se habilitan si el aporte a PROA del mes anterior alcanzó el mínimo contractual.</div></div><div id="status" class="status"></div><section class="panel"><div class="form"><div><label>Alumno PROA</label><input id="nombre" placeholder="Nombre completo"></div><div><label>Comisión</label><input id="importe" type="number" min="0" step="0.01" placeholder="500"></div><div><label>Observación</label><input id="obs" placeholder="Opcional"></div><button id="guardar">Registrar</button></div><div id="msg" class="msg"></div><table><thead><tr><th>Alumno PROA</th><th>Comisión</th><th>Observación</th><th></th></tr></thead><tbody id="rows"></tbody></table><div id="total" class="total"></div></section></main><script>const p=document.getElementById('periodo'),s=document.getElementById('status'),rows=document.getElementById('rows'),total=document.getElementById('total'),btn=document.getElementById('guardar'),msg=document.getElementById('msg');const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'});const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));p.value=new Date().toISOString().slice(0,7);async function load(){msg.textContent='';const r=await fetch('/api/comisiones-proa.php?periodo='+encodeURIComponent(p.value)),d=await r.json();if(!r.ok||!d.ok){s.textContent=d.error||'Error';return}btn.disabled=!d.habilitado;s.className='status '+(d.habilitado?'ok':'no');s.innerHTML=d.habilitado?`<div class="big">Comisiones habilitadas ✓</div><div class="muted">${esc(d.periodo_generador)} alcanzó el mínimo de ${money(d.minimo)}.</div>`:`<div class="big">Comisiones no habilitadas</div><div class="muted">Aporte de ${esc(d.periodo_generador)}: ${money(d.aporte_periodo_generador)} de ${money(d.minimo)}.</div>`;rows.innerHTML=d.comisiones.map(x=>`<tr><td>${esc(x.alumno_proa_nombre)}</td><td>${money(x.importe)}</td><td>${esc(x.observacion||'')}</td><td><button class="danger" data-del="${x.id}">Eliminar</button></td></tr>`).join('')||'<tr><td colspan="4">Sin comisiones registradas.</td></tr>';total.textContent='Total del mes: '+money(d.total)}p.onchange=load;btn.onclick=async()=>{msg.textContent='';const body={periodo:p.value,alumno_proa_nombre:document.getElementById('nombre').value.trim(),importe:Number(document.getElementById('importe').value||0),observacion:document.getElementById('obs').value.trim()};const r=await fetch('/api/comisiones-proa.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok){msg.textContent=d.error||'No se pudo registrar';return}document.getElementById('nombre').value='';document.getElementById('importe').value='';document.getElementById('obs').value='';await load()};rows.onclick=async e=>{const b=e.target.closest('[data-del]');if(!b)return;if(!confirm('¿Eliminar esta comisión?'))return;const r=await fetch('/api/comisiones-proa.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accion:'ELIMINAR',id:b.dataset.del})}),d=await r.json();if(!r.ok||!d.ok){alert(d.error||'Error');return}load()};load();</script></body></html>